const ids = ["G01","G02","G03","G04","G05","G06"];
const packets = {};
for (const id of ids) packets[id] = await tools.origin_packet({case_id: id});
const out = {cases: []};
for (const id of ids) {
  const c = packets[id].cases[0], e = c.evidence;
  const map = new Map();
  for (const q of c.query_ids) map.set(q, new Set());
  for (const en of e.entries) {
    if (!map.has(en.evidence_id)) map.set(en.evidence_id, new Set());
    map.get(en.evidence_id).add(en.source_id);
  }
  const queries = c.query_ids.map(q => ({material_id: q, origins: [...map.get(q)].sort()}));
  out.cases.push({id: c.id, recorded_origin_count: e.recorded_origin_count, independence: "unknown", queries});
}
console.log(JSON.stringify(out));
